const fail = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };

const s = ctx.statement || {};
const tx = (Array.isArray(s.transactions) ? s.transactions : []).map((t, i) => {
  const amount = num(t.amount), balance = num(t.balance);
  const type = String(t.type ?? '').toLowerCase();
  let kind = 'INVOICE';
  if (/pay|pmt|check|chk|remit|receipt/.test(type)) kind = 'PAYMENT';
  else if (/credit|\bcm\b|return|adj/.test(type) || (amount !== null && amount < 0)) kind = 'CREDIT';
  return { row: i + 1, kind, type: t.type ?? null, date: isoDate(t.date), date_raw: t.date ?? null,
           number: t.invoice_number ? String(t.invoice_number).trim() : (t.reference ? String(t.reference).trim() : null),
           po_number: t.po_number ?? null, amount, balance };
}).filter(t => t.number || t.amount !== null);

ctx.stmt = {
  statement_date: isoDate(s.statement_date), account_number: s.account_number ?? null, due_date: isoDate(s.due_date),
  previous_balance: num(s.previous_balance), payments: num(s.payments), credits: num(s.credits),
  current_charges: num(s.current_charges), amount_due: num(s.amount_due), transactions: tx,
