delete ctx.statement;

if (!ctx.vendor?.name) return fail('STATEMENT_FAILED', 'Statement has no vendor name');
if (!tx.length) return fail('STATEMENT_NO_TRANSACTIONS', 'No transaction lines could be read from the statement');

const dayMs = 86400000;
const dates = tx.map(t => t.date).filter(Boolean).sort();
let since;
