// Line-by-line match of statement transactions to Sage bills and credits.
const S = $('Build Config').first().json.cfg.STMT_RECON_CONFIG;
const CONFIG = { TOLERANCE: S.tolerance_dollars, SUFFIX_MATCH_MIN: S.suffix_match_min, PAGE_SIZE: S.sage_page_size };
const tol = CONFIG.TOLERANCE;
const ctx = JSON.parse(JSON.stringify($('Resolve Vendor').first().json));
delete ctx.sage_xml;
const fail = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };

const res = sageResults($input.first()?.json);
if (res.error) return fail('STATEMENT_FAILED', res.error);
const br = res.list.find(x => x.controlid === 'bills');
if (!br || br.status !== 'success') return fail('STATEMENT_FAILED', 'Sage bill query failed: ' + (sageErrors(br).join(' | ') || 'no detail'));
const bills = arr(br.data?.APBILL ?? br.data?.apbill);
if (bills.length >= CONFIG.PAGE_SIZE) ctx.warnings.push(`Sage returned ${CONFIG.PAGE_SIZE} bills (page limit); older bills may be missing`);
const cr = res.list.find(x => x.controlid === 'credits');
const credits = cr?.status === 'success' ? arr(cr.data?.APADJUSTMENT ?? cr.data?.apadjustment) : null;
if (credits === null) ctx.warnings.push('Sage credit lookup unavailable; statement credits not checked: ' + (sageErrors(cr).join(' | ') || 'no detail'));

const normId = v => String(v ?? '').replace(/[^A-Za-z0-9]/g, '').replace(/^0+/, '').toUpperCase();
const mdyIso = v => { const m = String(v ?? '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); return m ? `${m[3]}-${pad(m[1])}-${pad(m[2])}` : isoDate(v); };
const used = new Set();
function findDoc(list, t) {
  const key = normId(t.number);
  const free = list.filter(b => !used.has(b.RECORDNO));
  if (key) {
    const exact = free.find(b => normId(b.RECORDID) === key);
    if (exact) return exact;
    if (key.length >= CONFIG.SUFFIX_MATCH_MIN) {
      const near = free.filter(b => { const r = normId(b.RECORDID); return r.length >= CONFIG.SUFFIX_MATCH_MIN && (r.endsWith(key) || key.endsWith(r)); });
      if (near.length === 1) return near[0];
    }
  }
  if (t.po_number && t.amount !== null) {
    const po = normId(t.po_number);
    const byPo = free.filter(b => normId(b.DOCNUMBER).startsWith(po.slice(0, 9)) && Math.abs(Math.abs(num(b.TOTALENTERED) ?? 0) - Math.abs(t.amount)) <= tol);
    if (byPo.length === 1) return byPo[0];
  }
  return null;
}

const lines = ctx.stmt.transactions.map(t => {
  const base = { row: t.row, kind: t.kind, number: t.number, date: t.date || t.date_raw, statement_amount: t.amount, statement_balance: t.balance,
                 sage_bill: null, sage_amount: null, sage_due: null };
  if (t.kind === 'PAYMENT') return { ...base, result: 'PAYMENT_INFO' };
  if (t.kind === 'CREDIT' && credits === null) return { ...base, result: 'CREDIT_NOT_CHECKED' };
  const doc = findDoc(t.kind === 'CREDIT' ? credits : bills, t);
  if (!doc) return { ...base, result: t.kind === 'CREDIT' ? 'CREDIT_MISSING_IN_SAGE' : 'MISSING_IN_SAGE' };
  used.add(doc.RECORDNO);
  const sageAmt = num(doc.TOTALENTERED), sageDue = num(doc.TOTALDUE);
  const out = { ...base, sage_record_no: doc.RECORDNO, sage_bill: doc.RECORDID, sage_vendor: doc.VENDORID, sage_amount: sageAmt, sage_due: sageDue };
  if (t.amount !== null && sageAmt !== null && Math.abs(Math.abs(sageAmt) - Math.abs(t.amount)) > tol) return { ...out, result: 'AMOUNT_MISMATCH' };
  if (t.kind === 'INVOICE' && sageDue !== null && Math.abs(sageDue) <= tol && (t.balance === null || t.balance > tol)) return { ...out, result: 'PAID_IN_SAGE' };
  return { ...out, result: 'MATCHED' };
});

const stmtDate = ctx.stmt.statement_date;
const sageOnly = bills
  .filter(b => !used.has(b.RECORDNO) && (num(b.TOTALDUE) ?? 0) > tol && (!stmtDate || (mdyIso(b.WHENCREATED) || '') <= stmtDate))
  .map(b => ({ sage_record_no: b.RECORDNO, sage_bill: b.RECORDID, sage_vendor: b.VENDORID, date: mdyIso(b.WHENCREATED), sage_amount: num(b.TOTALENTERED), sage_due: num(b.TOTALDUE), result: 'OPEN_IN_SAGE_ONLY' }));

// Totals: statement amount due vs Sage open balance, after known timing items.
const openBills = bills.filter(b => !stmtDate || (mdyIso(b.WHENCREATED) || '') <= stmtDate).reduce((s, b) => s + Math.max(num(b.TOTALDUE) ?? 0, 0), 0);
const openCredits = (credits || []).reduce((s, c) => s + Math.abs(num(c.TOTALDUE) ?? 0), 0);
const sageOpen = round2(openBills - openCredits);
const timing = round2(lines.filter(l => l.result === 'PAID_IN_SAGE').reduce((s, l) => s + (l.statement_balance ?? l.statement_amount ?? 0), 0));
const stmtDue = ctx.stmt.amount_due;
const unexplained = stmtDue === null ? null : round2(stmtDue - sageOpen - timing);

const count = r => lines.filter(l => l.result === r).length;
const DISC = ['MISSING_IN_SAGE', 'CREDIT_MISSING_IN_SAGE', 'AMOUNT_MISMATCH'];
const discrepancies = lines.filter(l => DISC.includes(l.result)).length + sageOnly.length + (unexplained !== null && Math.abs(unexplained) > tol ? 1 : 0);

ctx.recon = {
  lines, sage_only: sageOnly,
  totals: { statement_due: stmtDue, sage_open: sageOpen, paid_in_sage_timing: timing, unexplained_difference: unexplained },
  counts: { matched: count('MATCHED'), missing_in_sage: count('MISSING_IN_SAGE'), credit_missing_in_sage: count('CREDIT_MISSING_IN_SAGE'),
            amount_mismatch: count('AMOUNT_MISMATCH'), paid_in_sage: count('PAID_IN_SAGE'), open_in_sage_only: sageOnly.length,
            payments: count('PAYMENT_INFO'), credits_not_checked: count('CREDIT_NOT_CHECKED') },
};
const c = ctx.recon.counts;
ctx.status = discrepancies ? 'STATEMENT_DISCREPANCIES' : 'RECONCILED';
ctx.reason = `${c.matched} matched, ${c.missing_in_sage} missing in Sage, ${c.credit_missing_in_sage} credits missing, ${c.amount_mismatch} amount mismatches, ` +
  `${c.paid_in_sage} paid in Sage, ${c.open_in_sage_only} open only in Sage; statement due ${stmtDue ?? 'n/a'} vs Sage open ${sageOpen}` +
  (unexplained !== null ? ` (unexplained ${unexplained})` : '');
return [{ json: ctx }];

const LEGAL_SUFFIXES = /\b(incorporated|llc|l\.l\.c|inc|corp|corporation|co|company|ltd|limited|llp|lp|enterprises?|facilit(?:y|ies)|industries|international|the)\b/g;
function normVendor(raw) {
  if (!raw) return '';
  return String(raw).toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[.,\/#!$%\^*;:{}=\-_`~()'"]/g, ' ')
    .replace(LEGAL_SUFFIXES, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const arr = v => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');

function sageCreds() {
  const s = $('Doppler').first().json;
  const c = {
    sender: s.SAGE_SENDER_ID ?? s.SAGE_COMPANY_ID,
    senderPw: s.SAGE_SENDER_PASSWORD ?? s.SAGE_COMPANY_PASSWORD,
    company: s.SAGE_COMPANY_ID,
    user: s.SAGE_USER_ID ?? s.USER_ID,
    userPw: s.SAGE_USER_PASSWORD ?? s.USER_PASSWORD,
  };
  const missing = Object.entries(c).filter(([, v]) => !v).map(([k]) => k);
  if (missing.length) throw new Error(`Doppler is missing Sage secrets: ${missing.join(', ')}`);
  return c;
}

// Login auth on every request (no session step). locationId scopes the request to the entity.
function sageEnvelope(locationId, functionsXml) {
  const c = sageCreds();
  return `<?xml version="1.0" encoding="UTF-8"?>` +
    `<request><control><senderid>${esc(c.sender)}</senderid><password>${esc(c.senderPw)}</password>` +
    `<controlid>${Date.now()}</controlid><uniqueid>false</uniqueid><dtdversion>3.0</dtdversion><includewhitespace>false</includewhitespace></control>` +
    `<operation><authentication><login><userid>${esc(c.user)}</userid><companyid>${esc(c.company)}</companyid><password>${esc(c.userPw)}</password>` +
    (locationId ? `<locationid>${esc(locationId)}</locationid>` : '') +
    `</login></authentication><content>${functionsXml}</content></operation></request>`;
}

// Collect every <errormessage> in a parsed Sage response.
function sageErrors(o, acc = []) {
  if (!o || typeof o !== 'object') return acc;
  for (const [k, v] of Object.entries(o)) {
    if (k === 'errormessage') {
      for (const e of arr(v?.error)) {
        acc.push([e.errorno, e.description, e.description2, e.correction].filter(x => typeof x === 'string' && x.trim()).join(' — '));
      }
    } else if (v && typeof v === 'object') {
      sageErrors(v, acc);
    }
  }
  return acc;
}

// Sage returns HTTP 200 even on failure, so the status has to be read from the body.
function sageResults(j) {
  const resp = j?.response;
  if (!resp) {
    const e = j?.error;
    return { error: 'No parseable response from Sage' + (e ? `: ${typeof e === 'string' ? e : (e.message || JSON.stringify(e))}` : '') };
  }
  if (resp.control?.status !== 'success') return { error: 'Sage control block failed: ' + (sageErrors(resp).join(' | ') || 'no detail') };
  if (resp.operation?.authentication?.status !== 'success') return { error: 'Sage login failed: ' + (sageErrors(resp).join(' | ') || 'no detail') };
  return { list: arr(resp.operation?.result) };
}

// Pick the Sage vendor ID(s), then query their bills and credits in one request.
const S = $('Build Config').first().json.cfg.STMT_RECON_CONFIG;
const ctx = JSON.parse(JSON.stringify($('Build Vendor Query').first().json));
delete ctx.sage_xml;
const fail = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };

const res = sageResults($input.first()?.json);
if (res.error) return fail('STATEMENT_FAILED', res.error);
const vr = res.list.find(x => x.controlid === 'vendorLookup');
if (!vr || vr.status !== 'success') return fail('STATEMENT_FAILED', 'Sage vendor lookup failed: ' + (sageErrors(vr).join(' | ') || 'no detail'));

const vendors = arr(vr.data?.VENDOR ?? vr.data?.vendor).filter(v => !v.STATUS || /^(active|t)$/i.test(String(v.STATUS)));
const target = normVendor(ctx.vendor.name);
let picks = vendors.filter(v => normVendor(v.NAME) === target);
if (!picks.length) picks = vendors.filter(v => { const n = normVendor(v.NAME); return n && target && (n.includes(target) || target.includes(n)); });
const code = ctx.location?.status === 'RESOLVED' ? ctx.location.code : null;
if (picks.length > 1 && code) {
  const local = picks.filter(v => String(v.VENDORID).toUpperCase().startsWith(code + '-'));
  if (local.length) picks = local;
}
if (!picks.length) return fail('VENDOR_NOT_FOUND', `No active Sage vendor matches "${ctx.vendor.name}"`);
if (picks.length > S.max_vendor_ids) return fail('VENDOR_AMBIGUOUS', `${picks.length} Sage vendors match "${ctx.vendor.name}"; too broad to reconcile`);
if (picks.length > 1) ctx.warnings.push(`Statement checked against ${picks.length} Sage vendor IDs: ${picks.map(v => v.VENDORID).join(', ')}`);
ctx.sage_vendors = picks.map(v => ({ id: v.VENDORID, name: v.NAME }));

const ids = picks.map(v => `<value>${esc(v.VENDORID)}</value>`).join('');
const since = esc(ctx.stmt.sage_since);
const fields = f => f.map(x => `<field>${x}</field>`).join('');
const billFields = fields(['RECORDNO', 'RECORDID', 'VENDORID', 'DOCNUMBER', 'WHENCREATED', 'WHENDUE', 'TOTALENTERED', 'TOTALPAID', 'TOTALDUE', 'STATE']);
const adjFields = fields(['RECORDNO', 'RECORDID', 'VENDORID', 'DOCNUMBER', 'WHENCREATED', 'TOTALENTERED', 'TOTALDUE', 'STATE']);
const filt = open => `<filter><and><in><field>VENDORID</field>${ids}</in><or><greaterthanorequalto><field>WHENCREATED</field><value>${since}</value></greaterthanorequalto>${open}</or></and></filter>`;
ctx.sage_xml = sageEnvelope(ctx.sage_login_location,
  `<function controlid="bills"><query><object>APBILL</object><select>${billFields}</select>` +
  filt(`<greaterthan><field>TOTALDUE</field><value>0</value></greaterthan>`) + `<pagesize>${S.sage_page_size}</pagesize></query></function>` +
  `<function controlid="credits"><query><object>APADJUSTMENT</object><select>${adjFields}</select>` +
  filt(`<notequalto><field>TOTALDUE</field><value>0</value></notequalto>`) + `<pagesize>${S.sage_page_size}</pagesize></query></function>`);
return [{ json: ctx }];

// Return the full context from whichever path ran.
let ctx = null;
try { ctx = $('Build Report').first().json.ctx; } catch (e) { ctx = null; }
if (!ctx) ctx = $json;
if (ctx.recon) {
  ctx.draft_created = (() => { try { return !!$('Outlook Vendor Draft').first().json.id; } catch (e) { return false; } })();
  if (ctx.draft_created) ctx.reason += '; vendor draft created';
}
return [{ json: ctx }];
